import{_ as i}from"./chunks/ArticleMetadata.DB-X1Xku.js";import{_ as r,J as c,l as n,b as p,e as d,p as h,M as u,s as b,q as g,f as m,a7 as k}from"./chunks/framework.ChxvFk4v.js";import"./chunks/theme.D0wAWFJR.js";const E=JSON.parse('{"title":"笔记导图 /notes/ — 实现说明与路线图","description":"","frontmatter":{},"headers":[],"relativePath":"public/notes/README.md","filePath":"public/notes/README.md","lastUpdated":1791521461000}'),x={name:"public/notes/README.md"};function q(t,a,f,v,C,P){const l=i,o=c("ClientOnly");return n(),p("div",null,[a[0]||(a[0]=d("h1",{id:"笔记导图-notes-—-实现说明与路线图",tabindex:"-1"},[h("笔记导图 /notes/ — 实现说明与路线图 "),d("a",{class:"header-anchor",href:"#笔记导图-notes-—-实现说明与路线图","aria-label":'Permalink to "笔记导图 /notes/ — 实现说明与路线图"'},"​")],-1)),u(o,null,{default:b(()=>{var e,s;return[(((e=t.$frontmatter)==null?void 0:e.aside)??!0)&&(((s=t.$frontmatter)==null?void 0:s.showArticleMetadata)??!0)?(n(),g(l,{key:0,article:t.$frontmatter},null,8,["article"])):m("",!0)]}),_:1}),a[1]||(a[1]=k(`<blockquote><p>考研复习用的 Markdown 思维导图笔记工具，基于 MindElixir，已部署在 <code>https://blog.lonemonk.xyz/notes/</code> 入口：数学考点取舍表 → 右上角「笔记导图」按钮</p></blockquote><hr><h2 id="一、markdown-语法速查" tabindex="-1">一、Markdown 语法速查 <a class="header-anchor" href="#一、markdown-语法速查" aria-label="Permalink to &quot;一、Markdown 语法速查&quot;">​</a></h2><p>所有语法写在节点文本里，保存后保留原文，编辑后不丢失。</p><h3 id="结构" tabindex="-1">结构 <a class="header-anchor" href="#结构" aria-label="Permalink to &quot;结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## 标题节点              → 解析时第一个节点作根</span></span>
<span class="line"><span>- 列表项                → 普通子节点</span></span>
<span class="line"><span>  - 缩进嵌套            → 更深层级（自动兼容 2/4 空格）</span></span></code></pre></div><h3 id="内容增强" tabindex="-1">内容增强 <a class="header-anchor" href="#内容增强" aria-label="Permalink to &quot;内容增强&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$(-1)^{i+j}$            → LaTeX 行内公式（KaTeX 渲染）</span></span>
<span class="line"><span>$$\\begin{pmatrix}A&amp;B\\end{pmatrix}$$  → LaTeX 块公式</span></span>
<span class="line"><span>![说明](图片地址)        → 图片（默认最大高 170px）</span></span>
<span class="line"><span>![说明](地址 =300x200)   → 图片（指定宽高）</span></span></code></pre></div><h3 id="链接" tabindex="-1">链接 <a class="header-anchor" href="#链接" aria-label="Permalink to &quot;链接&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[文字](https://...)     → 外链（新标签页打开）</span></span>
<span class="line"><span>https://www.example.com → 裸 URL（自动转链接）</span></span></code></pre></div><h3 id="笔记跳转" tabindex="-1">笔记跳转 <a class="header-anchor" href="#笔记跳转" aria-label="Permalink to &quot;笔记跳转&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[[目标笔记名]]                → 跳转到另一篇笔记</span></span>
<span class="line"><span>[自定义文字](note:目标笔记名) → 跳转（可改显示文字）</span></span></code></pre></div><h3 id="标签" tabindex="-1">标签 <a class="header-anchor" href="#标签" aria-label="Permalink to &quot;标签&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#标签名                  → 添加标签（侧栏底部可见，点击可筛选）</span></span>
<span class="line"><span>#高频 #难题              → 一个节点多个标签</span></span></code></pre></div><p><strong>解析优先级</strong>：图片 &gt; 笔记跳转 &gt; 链接 &gt; 裸 URL &gt; LaTeX &gt; 标签</p><hr><h2 id="二、文件夹分类" tabindex="-1">二、文件夹分类 <a class="header-anchor" href="#二、文件夹分类" aria-label="Permalink to &quot;二、文件夹分类&quot;">​</a></h2><h3 id="组织方式" tabindex="-1">组织方式 <a class="header-anchor" href="#组织方式" aria-label="Permalink to &quot;组织方式&quot;">​</a></h3><p>侧栏按文件夹分组，树形结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>📁 线性代数</span></span>
<span class="line"><span>  └─ 行列式</span></span>
<span class="line"><span>  └─ 矩阵</span></span>
<span class="line"><span>  └─ 向量组</span></span>
<span class="line"><span>📁 概率论</span></span>
<span class="line"><span>  └─ 随机变量</span></span>
<span class="line"><span>  └─ 数字特征</span></span>
<span class="line"><span>📥 未分类</span></span>
<span class="line"><span>  └─ 临时笔记</span></span></code></pre></div><h3 id="操作" tabindex="-1">操作 <a class="header-anchor" href="#操作" aria-label="Permalink to &quot;操作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>方式</th></tr></thead><tbody><tr><td>新建笔记时指定文件夹</td><td>弹出提示框，输入或选择文件夹名</td></tr><tr><td>导入笔记时指定文件夹</td><td>同上</td></tr><tr><td>移动笔记</td><td>笔记右侧 📁 按钮，选择文件夹编号或新建</td></tr><tr><td>删除文件夹</td><td>文件夹标题右侧 × 按钮，笔记移到「未分类」</td></tr><tr><td>折叠/展开</td><td>点击文件夹标题</td></tr><tr><td>未分类</td><td>始终在最后，放未归档的笔记</td></tr></tbody></table><h3 id="兼容旧数据" tabindex="-1">兼容旧数据 <a class="header-anchor" href="#兼容旧数据" aria-label="Permalink to &quot;兼容旧数据&quot;">​</a></h3><p>没有 <code>folder</code> 字段的旧笔记自动归入「未分类」，不影响已有数据。</p><hr><h2 id="三、视图控制" tabindex="-1">三、视图控制 <a class="header-anchor" href="#三、视图控制" aria-label="Permalink to &quot;三、视图控制&quot;">​</a></h2><h3 id="工具栏按钮" tabindex="-1">工具栏按钮 <a class="header-anchor" href="#工具栏按钮" aria-label="Permalink to &quot;工具栏按钮&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>⊕  全部展开     Ctrl+E</span></span>
<span class="line"><span>⊖  全部折叠     Ctrl+Shift+E</span></span>
<span class="line"><span>−  缩小         Ctrl+-</span></span>
<span class="line"><span>%  当前缩放     实时显示</span></span>
<span class="line"><span>+  放大         Ctrl++ 或 Ctrl+=</span></span>
<span class="line"><span>⤢  适配视图     Ctrl+0</span></span></code></pre></div><h3 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>Ctrl+E</code></td><td>全部展开</td></tr><tr><td><code>Ctrl+Shift+E</code></td><td>全部折叠</td></tr><tr><td><code>Ctrl+0</code></td><td>适配视图（自动缩放并居中）</td></tr><tr><td><code>Ctrl+ +</code> / <code>Ctrl+ -</code></td><td>放大 / 缩小</td></tr><tr><td><code>Ctrl+F</code></td><td>聚焦选中节点 / 退出焦点</td></tr><tr><td><code>Esc</code></td><td>退出焦点模式</td></tr><tr><td><code>Ctrl+滚轮</code></td><td>鼠标缩放</td></tr></tbody></table><h3 id="焦点模式" tabindex="-1">焦点模式 <a class="header-anchor" href="#焦点模式" aria-label="Permalink to &quot;焦点模式&quot;">​</a></h3><p>导图太大找不到目标节点时：</p><ol><li>点选一个节点</li><li>按 <code>Ctrl+F</code> 或点「聚焦」</li><li>只显示该节点的子树，其他节点隐藏</li><li>工具栏出现「焦点模式」橙色徽标</li><li>按 <code>Esc</code> 或再点「聚焦」退出</li></ol><h3 id="适配视图" tabindex="-1">适配视图 <a class="header-anchor" href="#适配视图" aria-label="Permalink to &quot;适配视图&quot;">​</a></h3><p>导图太大时按 <code>Ctrl+0</code>，自动：</p><ul><li>计算所有节点包围盒</li><li>缩放到刚好放进屏幕</li><li>居中显示</li></ul><hr><h2 id="四、标签系统" tabindex="-1">四、标签系统 <a class="header-anchor" href="#四、标签系统" aria-label="Permalink to &quot;四、标签系统&quot;">​</a></h2><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h3><p>在节点文本里写 <code>#标签名</code>，侧栏底部自动聚合：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#行列式 化简技巧        → 标签「行列式」</span></span>
<span class="line"><span>#高频 三步法            → 标签「高频」</span></span>
<span class="line"><span>#矩阵 基本运算 #高频    → 标签「矩阵」「高频」</span></span></code></pre></div><h3 id="操作-1" tabindex="-1">操作 <a class="header-anchor" href="#操作-1" aria-label="Permalink to &quot;操作&quot;">​</a></h3><ul><li>侧栏底部显示所有标签（绿色胶囊）</li><li>点击标签 → 打开第一篇含该标签的笔记</li><li>再次点击 → 取消筛选</li><li>标签来自所有笔记的节点文本，实时提取</li></ul><h3 id="与文件夹的区别" tabindex="-1">与文件夹的区别 <a class="header-anchor" href="#与文件夹的区别" aria-label="Permalink to &quot;与文件夹的区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>文件夹</th><th>标签</th></tr></thead><tbody><tr><td>归属</td><td>一个笔记只能在一个文件夹</td><td>一个笔记可以有多个标签</td></tr><tr><td>用途</td><td>主结构（科目/章节）</td><td>次级筛选（频率/难度/类型）</td></tr><tr><td>管理</td><td>侧栏树形</td><td>侧栏底部云</td></tr></tbody></table><hr><h2 id="五、功能列表" tabindex="-1">五、功能列表 <a class="header-anchor" href="#五、功能列表" aria-label="Permalink to &quot;五、功能列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>位置</th><th>说明</th></tr></thead><tbody><tr><td>新建笔记</td><td>侧栏底部</td><td>输入名称 + 选择文件夹</td></tr><tr><td>导入 Markdown</td><td>侧栏底部</td><td>粘贴 AI 生成的 Markdown，转成导图</td></tr><tr><td>编辑 Markdown 源</td><td>工具栏</td><td>直接改当前笔记的 Markdown 源，覆盖导图</td></tr><tr><td>笔记间跳转</td><td>节点内点击</td><td><code>[[x]]</code> 或 <code>(note:x)</code>，橙色加粗链接</td></tr><tr><td>返回上一笔记</td><td>工具栏</td><td>跳转栈，A→B→C 可逐层返回</td></tr><tr><td>改名</td><td>工具栏</td><td>重命名笔记</td></tr><tr><td>移动文件夹</td><td>笔记右侧 📁</td><td>移到其他文件夹或新建</td></tr><tr><td>导出 JSON</td><td>工具栏</td><td>导出当前笔记完整数据（含文件夹信息）</td></tr><tr><td>重置</td><td>工具栏</td><td>清空当前笔记所有编辑</td></tr><tr><td>云同步</td><td>工具栏</td><td>jsonbin.io 多设备同步</td></tr><tr><td>搜索节点</td><td>工具栏</td><td>当前笔记内模糊搜索，自动展开定位</td></tr><tr><td>全部展开</td><td>工具栏 ⊕</td><td>展开所有折叠节点</td></tr><tr><td>全部折叠</td><td>工具栏 ⊖</td><td>折叠所有子节点</td></tr><tr><td>缩放控制</td><td>工具栏 −/+/⤢</td><td>缩小/放大/适配视图</td></tr><tr><td>聚焦节点</td><td>工具栏「聚焦」</td><td>只显示选中节点子树，点「聚焦」或 Esc 退出</td></tr><tr><td>文件夹管理</td><td>侧栏</td><td>新建/删除/折叠/展开</td></tr><tr><td>标签筛选</td><td>侧栏底部</td><td>按标签聚合浏览</td></tr></tbody></table><hr><h2 id="六、数据架构" tabindex="-1">六、数据架构 <a class="header-anchor" href="#六、数据架构" aria-label="Permalink to &quot;六、数据架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>localStorage:</span></span>
<span class="line"><span>  mm_notes_list        → 笔记索引 [{id, name, folder, created}]</span></span>
<span class="line"><span>  mm_notes:&lt;id&gt;        → 单篇笔记完整数据 {nodeData, arrows, summaries, direction, theme}</span></span>
<span class="line"><span>  mm_notes_sync_config → 云同步凭证 {keyId, accessKey, binId}</span></span>
<span class="line"><span>  mm_notes_last_sync   → 上次同步时间</span></span></code></pre></div><p><strong>关键不变式</strong>：<code>nodeData</code> 里每个节点的 <code>topic</code> 字段永远是原始纯文本（含 <code>$...$</code>、<code>[[x]]</code>、<code>![...](...)</code>、<code>#标签</code> 语法），<code>dangerouslySetInnerHTML</code> 是派生的视图层。每次加载都从 <code>topic</code> 重新生成 HTML（<code>applyInlineHtml</code>），保证编辑→保存→重新打开不丢失公式/链接/图片/标签。</p><hr><h2 id="七、技术实现" tabindex="-1">七、技术实现 <a class="header-anchor" href="#七、技术实现" aria-label="Permalink to &quot;七、技术实现&quot;">​</a></h2><h3 id="与-mindelixir-的关系" tabindex="-1">与 MindElixir 的关系 <a class="header-anchor" href="#与-mindelixir-的关系" aria-label="Permalink to &quot;与 MindElixir 的关系&quot;">​</a></h3><p>库一行没改。所有扩展通过公开 API 实现：</p><ul><li><code>getData()</code> — 数据导出</li><li><code>bus.addListener(&quot;operation&quot;, cb)</code> — 编辑事件（自动保存）</li><li>节点的 <code>dangerouslySetInnerHTML</code> — 富文本渲染</li><li><code>refresh()</code> — 图片加载后重算布局</li></ul><p>部署时唯一改动：ESM → 全局脚本（支持 <code>file://</code> 本地打开）。</p><h3 id="文件结构" tabindex="-1">文件结构 <a class="header-anchor" href="#文件结构" aria-label="Permalink to &quot;文件结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/public/notes/</span></span>
<span class="line"><span>├── index.html                  # 主页面（解析器 + UI + 同步）</span></span>
<span class="line"><span>├── README.md                   # 本文档</span></span>
<span class="line"><span>└── vendor/</span></span>
<span class="line"><span>    ├── mind-elixir.global.js   # 思维导图引擎（官方构建，未修改）</span></span>
<span class="line"><span>    └── katex/</span></span>
<span class="line"><span>        ├── katex.min.js        # LaTeX 渲染</span></span>
<span class="line"><span>        ├── katex.min.css</span></span>
<span class="line"><span>        └── fonts/*.woff2       # 20 个字体文件</span></span></code></pre></div><hr><h2 id="八、未来计划" tabindex="-1">八、未来计划 <a class="header-anchor" href="#八、未来计划" aria-label="Permalink to &quot;八、未来计划&quot;">​</a></h2><h3 id="p0-核心体验" tabindex="-1">P0（核心体验） <a class="header-anchor" href="#p0-核心体验" aria-label="Permalink to &quot;P0（核心体验）&quot;">​</a></h3><ol><li><strong>全局搜索</strong> — 搜所有笔记的节点，结果列表点击跳转</li><li><strong>双链反查</strong> — &quot;谁引用了我&quot;，看哪些笔记跳到了当前节点</li><li><strong>移动端优化</strong> — 当前可用但体验一般</li></ol><h3 id="p1-内容能力" tabindex="-1">P1（内容能力） <a class="header-anchor" href="#p1-内容能力" aria-label="Permalink to &quot;P1（内容能力）&quot;">​</a></h3><ol start="4"><li><strong>导出 PDF / PNG</strong> — 接 html2canvas 或打印 CSS</li><li><strong>版本历史</strong> — 云同步时存快照，可回滚</li><li><strong>笔记模板</strong> — 预设常见结构（如&quot;题型模板：适用场景→解题步骤→易错点&quot;）</li><li><strong>快捷键面板</strong> — 官方快捷键暴露给用户查看</li></ol><h3 id="p2-扩展" tabindex="-1">P2（扩展） <a class="header-anchor" href="#p2-扩展" aria-label="Permalink to &quot;P2（扩展）&quot;">​</a></h3><ol start="8"><li><strong>多主题皮肤</strong> — 官方只有两套，可定制颜色方案</li><li><strong>统计面板</strong> — 笔记数、节点数、最近编辑时间</li><li><strong>Markdown 导出整本</strong> — 一键导出所有笔记为一个 .md 文件</li><li><strong>离线 PWA</strong> — Service Worker 缓存，断网可用</li><li><strong>图片上传</strong> — 本地文件上传到图床，支持本地图片</li></ol><hr><h2 id="九、技术备注" tabindex="-1">九、技术备注 <a class="header-anchor" href="#九、技术备注" aria-label="Permalink to &quot;九、技术备注&quot;">​</a></h2><h3 id="mindelixir-对外-api-22-个" tabindex="-1">MindElixir 对外 API（22 个） <a class="header-anchor" href="#mindelixir-对外-api-22-个" aria-label="Permalink to &quot;MindElixir 对外 API（22 个）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>init / refresh / getData / getDataString / getDataMd</span></span>
<span class="line"><span>expandNode / focusNode / toCenter / selectNode / selectNodes</span></span>
<span class="line"><span>unselectNode / unselectNodes / clearSelection / cancelFocus</span></span>
<span class="line"><span>enableEdit / disableEdit / scale / initLeft / initRight / initSide</span></span>
<span class="line"><span>setLocale / install</span></span></code></pre></div><h3 id="视图控制实现" tabindex="-1">视图控制实现 <a class="header-anchor" href="#视图控制实现" aria-label="Permalink to &quot;视图控制实现&quot;">​</a></h3><ul><li><strong>全部展开/折叠</strong>：递归修改 <code>nodeData</code> 的 <code>expanded</code> 字段，调 <code>mind.refresh()</code></li><li><strong>缩放</strong>：用库的 <code>scale(v)</code> API，监听 <code>bus.fire(&#39;scale&#39;)</code> 更新标签</li><li><strong>适配视图</strong>：测量所有 <code>me-node</code> 包围盒 → 计算目标缩放 → <code>mind.scale(v)</code> → 滚动居中</li><li><strong>焦点模式</strong>：用库的 <code>focusNode(nodeObj)</code> / <code>cancelFocus()</code>，监听 <code>isFocusMode</code> 显示徽标</li><li><strong>快捷键</strong>：全局 <code>keydown</code> 监听，检查 <code>Ctrl+key</code> 组合，输入框内不触发</li></ul><h3 id="已知限制" tabindex="-1">已知限制 <a class="header-anchor" href="#已知限制" aria-label="Permalink to &quot;已知限制&quot;">​</a></h3><ol><li><strong>官方 <code>getDataMd()</code> 丢公式和链接</strong> — 用自己的 <code>nodeDataToMd()</code> 替代，保留原始 topic</li><li><strong>千节点以上渲染慢</strong> — 建议单篇笔记控制在 200 节点以内</li><li><strong>图片必须用外链 URL</strong> — 不支持本地文件上传（需要后端图床）</li><li><strong>KaTeX 字体 1.2MB</strong> — 首次加载慢，浏览器缓存后不慢</li></ol><h3 id="踩过的坑" tabindex="-1">踩过的坑 <a class="header-anchor" href="#踩过的坑" aria-label="Permalink to &quot;踩过的坑&quot;">​</a></h3><ol><li><code>topic</code> 用 <code>textContent</code> 渲染，不解析 HTML → 必须用 <code>dangerouslySetInnerHTML</code></li><li><code>getData()</code> 在节点带 <code>dangerouslySetInnerHTML</code> 时，topic 会变成 HTML 字符串 → 必须用 <code>applyInlineHtml</code> 从纯文本重新生成</li><li>MindElixir 是 ESM，<code>file://</code> 下 ESM 被 CORS 拦 → 转全局脚本 + IIFE</li><li>Cloudflare 缓存旧的 404 → 文件加版本号重命名</li><li>KaTeX 字体路径相对页面解析 → 用 <code>./vendor/katex/fonts/</code></li><li>图片异步加载导致节点宽度变化 → 监听 <code>load</code> 事件后调 <code>mind.refresh()</code></li></ol><hr><p><em>最后更新：2026-10-08</em></p>`,80))])}const S=r(x,[["render",q]]);export{E as __pageData,S as default};
